import sqlite3

_SELECT = """
SELECT e.id, e.amount_cents, e.description, c.name AS category, e.spent_on
FROM expenses e
JOIN categories c ON c.id = e.category_id
"""


def add(
    conn: sqlite3.Connection,
    amount_cents: int,
    description: str,
    category_id: int,
    spent_on: str,
    created_at: str,
) -> int:
    cur = conn.execute(
        "INSERT INTO expenses (amount_cents, description, category_id, spent_on, created_at)"
        " VALUES (?, ?, ?, ?, ?)",
        (amount_cents, description, category_id, spent_on, created_at),
    )
    return int(cur.lastrowid)


def get(conn: sqlite3.Connection, expense_id: int) -> sqlite3.Row | None:
    return conn.execute(_SELECT + " WHERE e.id = ?", (expense_id,)).fetchone()


def list_expenses(conn: sqlite3.Connection, month: str | None = None) -> list[sqlite3.Row]:
    if month is None:
        return conn.execute(_SELECT + " ORDER BY e.spent_on, e.id").fetchall()
    return conn.execute(
        _SELECT + " WHERE substr(e.spent_on, 1, 7) = ? ORDER BY e.spent_on, e.id",
        (month,),
    ).fetchall()


def delete(conn: sqlite3.Connection, expense_id: int) -> bool:
    cur = conn.execute("DELETE FROM expenses WHERE id = ?", (expense_id,))
    return cur.rowcount > 0


def totals_by_category(conn: sqlite3.Connection, month: str) -> list[sqlite3.Row]:
    return conn.execute(
        "SELECT c.name AS category, SUM(e.amount_cents) AS total_cents"
        " FROM expenses e JOIN categories c ON c.id = e.category_id"
        " WHERE substr(e.spent_on, 1, 7) = ?"
        " GROUP BY c.id ORDER BY total_cents DESC, c.name",
        (month,),
    ).fetchall()


def sum_for_category(conn: sqlite3.Connection, category_id: int, month: str) -> int:
    row = conn.execute(
        "SELECT COALESCE(SUM(amount_cents), 0) AS total FROM expenses"
        " WHERE category_id = ? AND substr(spent_on, 1, 7) = ?",
        (category_id, month),
    ).fetchone()
    return int(row["total"])

import sqlite3
from dataclasses import dataclass
from datetime import date, datetime

from ledgerly import config, money
from ledgerly.errors import NotFoundError, ValidationError
from ledgerly.logging_setup import get_logger
from ledgerly.repositories import expenses as expense_repo
from ledgerly.services import category_service

log = get_logger(__name__)


@dataclass(frozen=True)
class ExpenseRecord:
    id: int
    amount_cents: int
    description: str
    category: str
    spent_on: str


def _to_record(row: sqlite3.Row) -> ExpenseRecord:
    return ExpenseRecord(
        id=row["id"],
        amount_cents=row["amount_cents"],
        description=row["description"],
        category=row["category"],
        spent_on=row["spent_on"],
    )


def validate_month(month: str) -> str:
    try:
        datetime.strptime(month, config.MONTH_FORMAT)
    except (TypeError, ValueError):
        raise ValidationError(f"Month must look like YYYY-MM, got {month!r}") from None
    return month


def add_expense(
    conn: sqlite3.Connection,
    amount_text: str,
    description: str,
    category_name: str,
    spent_on: str | None = None,
) -> ExpenseRecord:
    cents = money.parse_amount(amount_text)
    text = (description or "").strip()
    if not text:
        raise ValidationError("Description is required")
    if len(text) > config.MAX_DESCRIPTION_LEN:
        raise ValidationError(
            f"Description is longer than {config.MAX_DESCRIPTION_LEN} characters"
        )
    category = category_service.require_category(conn, category_name)
    when = (spent_on or "").strip() or date.today().strftime(config.DATE_FORMAT)

    created_at = datetime.now().isoformat(timespec="seconds")
    expense_id = expense_repo.add(conn, cents, text, category["id"], when, created_at)
    conn.commit()
    log.info("added expense %s (%s cents) to %s", expense_id, cents, category["name"])
    return get_expense(conn, expense_id)


def get_expense(conn: sqlite3.Connection, expense_id: int) -> ExpenseRecord:
    row = expense_repo.get(conn, expense_id)
    if row is None:
        raise NotFoundError(f"No expense with id {expense_id}")
    return _to_record(row)


def list_expenses(conn: sqlite3.Connection, month: str | None = None) -> list[ExpenseRecord]:
    if month is not None:
        validate_month(month)
    return [_to_record(row) for row in expense_repo.list_expenses(conn, month)]


def delete_expense(conn: sqlite3.Connection, expense_id: int) -> None:
    if not expense_repo.delete(conn, expense_id):
        raise NotFoundError(f"No expense with id {expense_id}")
    conn.commit()
    log.info("deleted expense %s", expense_id)

import sqlite3
from dataclasses import dataclass

from ledgerly.repositories import expenses as expense_repo
from ledgerly.services.expense_service import validate_month


@dataclass(frozen=True)
class CategoryTotal:
    category: str
    total_cents: int


@dataclass(frozen=True)
class MonthlyReport:
    month: str
    lines: list[CategoryTotal]

    @property
    def total_cents(self) -> int:
        return sum(line.total_cents for line in self.lines)


def monthly_report(conn: sqlite3.Connection, month: str) -> MonthlyReport:
    validate_month(month)
    rows = expense_repo.totals_by_category(conn, month)
    lines = [CategoryTotal(row["category"], int(row["total_cents"])) for row in rows]
    return MonthlyReport(month=month, lines=lines)

"""Application error hierarchy. Each error maps to a process exit code."""


class AppError(Exception):
    exit_code = 1

    def __init__(self, message: str, exit_code: int | None = None) -> None:
        super().__init__(message)
        if exit_code is not None:
            self.exit_code = exit_code


class ValidationError(AppError):
    exit_code = 2


class NotFoundError(AppError):
    exit_code = 3


class ConflictError(AppError):
    exit_code = 4

"""Money helpers. Amounts are carried around as integer cents."""

from decimal import Decimal, InvalidOperation

from ledgerly import config
from ledgerly.errors import ValidationError


def parse_amount(text: str) -> int:
    """Convert user text such as "12.5" into integer cents (1250)."""
    raw = (text or "").strip()
    if not raw:
        raise ValidationError("Amount is required")
    try:
        value = Decimal(raw)
    except InvalidOperation:
        raise ValidationError(f"Invalid amount: {raw!r}") from None
    if not value.is_finite():
        raise ValidationError(f"Invalid amount: {raw!r}")
    if value.as_tuple().exponent < -2:
        raise ValidationError("Amount cannot have more than 2 decimal places")
    if value <= 0:
        raise ValidationError("Amount must be greater than zero")
    return int(value * 100)


def format_cents(cents: int, currency: str = config.DEFAULT_CURRENCY) -> str:
    sign = "-" if cents < 0 else ""
    whole, fraction = divmod(abs(cents), 100)
    return f"{sign}{whole:,}.{fraction:02d} {currency}"
